(function() {

    ['nova-xray', 'nova-toast', 'nova-modal-overlay', 'nova-hunter-btn', 'nova-hunter-modal'].forEach(id => {
        let el = document.getElementById(id);
        if(el) el.remove();
    });

    console.log("🚀 X-Ray Bot 8.0 (Stealth Duo Edition) Injected!");


    const style = document.createElement('style');
    style.textContent = `
        #nova-xray { position: fixed; top: 30px; left: 10px; z-index: 2147483647; display: flex; flex-direction: column; gap: 8px; background: rgba(0,0,0,0.4); padding: 8px; border-radius: 30px; cursor: move; user-select: none; touch-action: none; box-shadow: 0 4px 15px rgba(0,0,0,0.3); backdrop-filter: blur(5px); }
        .nx-btn { background: #000; color: #fff; border: 2px solid #333; border-radius: 50%; width: 40px; height: 40px; font-size: 18px; display: flex; align-items: center; justify-content: center; cursor: pointer; transition: 0.3s; outline: none; }
        .nx-btn.active { background: #ea4335; border-color: #ea4335; box-shadow: 0 0 10px rgba(234,67,53,0.6); }

        #nova-toast { position: fixed; bottom: -60px; left: 50%; transform: translateX(-50%); background: #202124; color: #fff; padding: 12px 24px; border-radius: 30px; z-index: 2147483647; font-family: sans-serif; font-size: 14px; font-weight: bold; transition: bottom 0.4s cubic-bezier(0.18, 0.89, 0.32, 1.28); pointer-events: none; border: 1px solid #4285f4; box-shadow: 0 5px 15px rgba(0,0,0,0.5); white-space: nowrap; }
        #nova-toast.show { bottom: 50px; }
    `;
    document.head.appendChild(style);


    const menu = document.createElement('div'); menu.id = 'nova-xray';
    const btnEdit = document.createElement('button'); btnEdit.className = 'nx-btn'; btnEdit.innerText = '✍️';
    const btnPass = document.createElement('button'); btnPass.className = 'nx-btn'; btnPass.innerText = '👁️';

    menu.appendChild(btnEdit); menu.appendChild(btnPass);
    document.body.appendChild(menu);


    const toast = document.createElement('div'); toast.id = 'nova-toast'; document.body.appendChild(toast);
    let toastTimer;
    function reportToast(msg) {
        toast.innerText = msg; toast.classList.add('show');
        clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove('show'), 2500);
    }

    // ৪. ড্র্যাগ (Drag) লজিক
    let isDragging = false, startX, startY, initX, initY;
    function dragStart(e) {
        isDragging = false; let evt = e.type.includes('touch') ? e.touches[0] : e;
        startX = evt.clientX; startY = evt.clientY; let rect = menu.getBoundingClientRect();
        initX = rect.left; initY = rect.top;
        document.addEventListener(e.type.includes('touch') ? 'touchmove' : 'mousemove', dragMove, {passive: false});
        document.addEventListener(e.type.includes('touch') ? 'touchend' : 'mouseup', dragEnd);
    }
    function dragMove(e) {
        let evt = e.type.includes('touch') ? e.touches[0] : e;
        let dx = evt.clientX - startX; let dy = evt.clientY - startY;
        if (Math.abs(dx) > 5 || Math.abs(dy) > 5) {
            isDragging = true; e.preventDefault();
            menu.style.left = (initX + dx) + 'px'; menu.style.top = (initY + dy) + 'px';
            menu.style.right = 'auto'; menu.style.bottom = 'auto';
        }
    }
    function dragEnd() {
        document.removeEventListener('mousemove', dragMove); document.removeEventListener('mouseup', dragEnd);
        document.removeEventListener('touchmove', dragMove); document.removeEventListener('touchend', dragEnd);
    }
    menu.addEventListener('mousedown', dragStart); menu.addEventListener('touchstart', dragStart, {passive: false});

    // ৫. ফিচার লজিক

    // ✍️ Edit Mode (পেজের যেকোনো লেখা এডিট করার জন্য)
    btnEdit.onclick = () => {
        if (isDragging) return;
        let isEditOn = document.designMode === 'on';
        document.designMode = isEditOn ? 'off' : 'on';
        btnEdit.classList.toggle('active', !isEditOn);
        reportToast(!isEditOn ? "✍️ Edit Mode On!" : "✍️ Edit Mode Off!");
    };

    // 👁️ Show Password (লুকানো পাসওয়ার্ড দেখার জন্য)
    let isPassMode = false;
    btnPass.onclick = () => {
        if (isDragging) return;
        isPassMode = !isPassMode; let found = false;
        document.querySelectorAll('input').forEach(inp => {
            if (isPassMode && inp.type === 'password') { inp.dataset.wasPass = 'true'; inp.type = 'text'; found = true; } 
            else if (!isPassMode && inp.dataset.wasPass === 'true') { inp.type = 'password'; delete inp.dataset.wasPass; found = true; }
        });
        btnPass.classList.toggle('active', isPassMode);
        reportToast(isPassMode ? (found ? "👁️ Passwords Unmasked!" : "👁️ No passwords found.") : "👁️ Passwords Hidden.");
    };

})();
